def es_anagrama(a, b):
    if len(a) != len(b):
        return False
    conteo = {}
    for c in a:
        conteo[c] = conteo.get(c, 0) + 1
    for c in b:
        if conteo.get(c, 0) == 0:
            return False
        conteo[c] -= 1
    return True

