ejercicios.solucion:
def hay_duplicados(nums):
    return len(set(nums)) != len(nums)


def primer_duplicado(nums):
    vistos = set()
    for n in nums:
        if n in vistos:
            return n
        vistos.add(n)
    return None


def contar_duplicados(nums):
    conteo = {}
    for n in nums:
        conteo[n] = conteo.get(n, 0) + 1
    return {k: v for k, v in conteo.items() if v > 1}

