from collections import deque


class Cola:
    def __init__(self):
        self.items = deque()

    def encolar(self, x):
        self.items.append(x)

    def desencolar(self):
        if self.vacia():
            raise IndexError("cola vacia")
        return self.items.popleft()

    def frente(self):
        if self.vacia():
            raise IndexError("cola vacia")
        return self.items[0]

    def vacia(self):
        return len(self.items) == 0

    def __len__(self):
        return len(self.items)

