def busqueda_binaria(nums, objetivo):
    izq, der = 0, len(nums) - 1
    while izq <= der:
        medio = (izq + der) // 2
        if nums[medio] == objetivo:
            return medio
        if nums[medio] < objetivo:
            izq = medio + 1
        else:
            der = medio - 1
    return -1


def primer_indice(nums, objetivo):
    izq, der = 0, len(nums) - 1
    respuesta = -1
    while izq <= der:
        medio = (izq + der) // 2
        if nums[medio] == objetivo:
            respuesta = medio
            der = medio - 1
        elif nums[medio] < objetivo:
            izq = medio + 1
        else:
            der = medio - 1
    return respuesta

