def rotar(nums, k):
    n = len(nums)
    if n == 0:
        return
    k %= n

    def invertir(i, j):
        while i < j:
            nums[i], nums[j] = nums[j], nums[i]
            i += 1
            j -= 1

    invertir(0, n - 1)
    invertir(0, k - 1)
    invertir(k, n - 1)

