ejercicios.solucion:
def suma_maxima_k(nums, k):
    if k < 1 or k > len(nums):
        return None
    suma = sum(nums[:k])
    mejor = suma
    for i in range(k, len(nums)):
        suma += nums[i] - nums[i - k]
        mejor = max(mejor, suma)
    return mejor

