class NodoBST:
    def __init__(self, valor):
        self.valor = valor
        self.izq = None
        self.der = None


class BST:
    def __init__(self):
        self.raiz = None

    def insertar(self, valor):
        nuevo = NodoBST(valor)
        if self.raiz is None:
            self.raiz = nuevo
            return
        actual = self.raiz
        while True:
            if valor == actual.valor:
                return
            if valor < actual.valor:
                if actual.izq is None:
                    actual.izq = nuevo
                    return
                actual = actual.izq
            else:
                if actual.der is None:
                    actual.der = nuevo
                    return
                actual = actual.der

    def buscar(self, valor):
        actual = self.raiz
        while actual is not None:
            if valor == actual.valor:
                return True
            actual = actual.izq if valor < actual.valor else actual.der
        return False

    def inorden(self):
        resultado = []

        def visitar(nodo):
            if nodo is None:
                return
            visitar(nodo.izq)
            resultado.append(nodo.valor)
            visitar(nodo.der)

        visitar(self.raiz)
        return resultado

    def altura(self):
        def h(nodo):
            if nodo is None:
                return 0
            return 1 + max(h(nodo.izq), h(nodo.der))

        return h(self.raiz)

