ejercicios.solucion:
def longitud_substring_unico(s):
    ultima = {}
    izq = 0
    mejor = 0
    for der, c in enumerate(s):
        if c in ultima and ultima[c] >= izq:
            izq = ultima[c] + 1
        ultima[c] = der
        mejor = max(mejor, der - izq + 1)
    return mejor
